<script setup>import * as Vue from 'vue';import {component} from '../../../../rancher-common-ui/client/index.mjs';import {leavePrompt,finishEditorLeave,stayInEditor} from '../data/editor-session';const Modal=component('Modal',Vue);</script><template><Modal v-if="leavePrompt" title="Unsaved Changes" @close="stayInEditor"><p>Save a working draft for this session, discard changes, or keep editing.</p><template #actions><button type="button" @click="finishEditorLeave(true)">Save Draft And Leave</button><button type="button" @click="finishEditorLeave(false)">Discard Changes</button><button type="button" @click="stayInEditor">Stay On This Page</button></template></Modal></template>
